import{_ as a,o as p,c as r,a2 as e}from"./chunks/framework.EUByU7Iq.js";const v=JSON.parse('{"title":"《佛经 · 八大人觉经》","description":"","frontmatter":{"title":"《佛经 · 八大人觉经》","date":"2026-11-23T00:00:00.000Z","categories":["美文","佛经"],"collection":"《佛经 · 八大人觉经》","tags":["佛经","后汉"],"poem":true,"poem_quote":false,"merged":true,"pieces":1,"author":"安世高 译","source_book":"佛经"},"headers":[],"relativePath":"blogs/佛经·八大人觉经/index.md","filePath":"blogs/佛经·八大人觉经/index.md"}'),i={name:"blogs/佛经·八大人觉经/index.md"};function t(l,s,c,o,d,u){return p(),r("div",null,[...s[0]||(s[0]=[e('<h1 id="《佛经-·-八大人觉经》" tabindex="-1">《佛经 · 八大人觉经》 <a class="header-anchor" href="#《佛经-·-八大人觉经》" aria-label="Permalink to &quot;《佛经 · 八大人觉经》&quot;">​</a></h1><p class="poem-meta">后汉 · 安世高 译</p><p>全文 10 段，经文与白话逐段对照，收录完整。</p><div class="merged-book"><h3 id="八大人觉经" tabindex="-1">八大人觉经 <a class="header-anchor" href="#八大人觉经" aria-label="Permalink to &quot;八大人觉经&quot;">​</a></h3><div class="sutra"><div class="su-pair"><p class="su-org">为佛弟子，常于昼夜，至心诵念八大人觉：</p><p class="su-tra">凡是佛的弟子，应当在白天和夜里，至诚恳切地诵念下面这八件大人（佛与菩萨）所觉悟的事：</p></div><div class="su-pair"><p class="su-org">第一觉悟：世间无常；国土危脆，四大苦空，五阴无我，生灭变异，虚伪无主，心是恶源，形为罪薮，如是观察，渐离生死。</p><p class="su-tra">第一件要觉悟的：世间的一切都不恒常，国土也不坚实、随时会崩坏；地、水、火、风四大拼成的这个身心，本质是苦、是空；色、受、想、行、识五蕴里找不到一个真正做主的我。生命刹那生灭、时时变异，虚妄不实、没有主宰；心念是众恶的源头，形骸是众罪的聚集处。这样如实地观察下去，就能渐渐走出轮回生死。</p></div><div class="su-pair"><p class="su-org">第二觉知：多欲为苦；生死疲劳，从贪欲起，少欲无为，身心自在。</p><p class="su-tra">第二件要觉知的：欲望多是苦。生死轮回里的疲惫劳苦，都从贪欲生起；能少欲、能不着意妄为，身心才得自在。</p></div><div class="su-pair"><p class="su-org">第三觉知：心无厌足，唯得多求，增长罪恶；菩萨不尔，常念知足，安贫守道，唯慧是业。</p><p class="su-tra">第三件要觉知的：人的心永远不满足，只是一个劲儿要求更多，于是罪恶越增长越多。菩萨不这样——菩萨常常念着知足，安于清贫、守住正道，只把求智慧当作自己的事业。</p></div><div class="su-pair"><p class="su-org">第四觉知：懈怠坠落；常行精进，破烦恼恶，摧伏四魔，出阴界狱。</p><p class="su-tra">第四件要觉知的：一懈怠就会堕落。所以要常常精进，破掉烦恼与恶法，摧伏蕴魔、烦恼魔、死魔、天魔这四魔，走出五蕴与十八界围成的牢狱。</p></div><div class="su-pair"><p class="su-org">第五觉悟：愚痴生死；菩萨常念，广学多闻，增长智慧，成就辩才，教化一切，悉以大乐。</p><p class="su-tra">第五件要觉悟的：愚痴是生死的根子。菩萨常常念着要广学多闻，增长智慧，成就辩才，教化一切，让一切都得到究竟的大乐。</p></div><div class="su-pair"><p class="su-org">第六觉知：贫苦多怨，横结恶缘；菩萨布施，等念怨亲，不念旧恶，不憎恶人。</p><p class="su-tra">第六件要觉知的：贫穷苦楚的人容易生怨，无缘无故就结下恶缘。菩萨行布施时，怨家与亲人一样看待，不记旧的恶，不憎可恶的人。</p></div><div class="su-pair"><p class="su-org">第七觉悟：五欲过患；虽为俗人，不染世乐，常念三衣，瓦钵法器，志愿出家，守道清白，梵行高远，慈悲一切。</p><p class="su-tra">第七件要觉悟的：财、色、名、食、睡这五欲有过患。学道的人虽然身在世俗，也不沾染世间的享乐；常常记着三衣、瓦钵这些法器，发愿离欲出家，守道清白，梵行高远，慈悲一切。</p></div><div class="su-pair"><p class="su-org">第八觉知：生死炽然，苦恼无量；发大乘心，普济一切，愿代众生，受无量苦，令诸众生，毕竟大乐。</p><p class="su-tra">第八件要觉知的：生死之火烧得正旺，苦恼无量。应当发起大乘的心，普济一切，愿意替众生承受无量的苦，让一切众生都得究竟的大乐。</p></div><div class="su-pair"><p class="su-org">如此八事，乃是诸佛，菩萨大人，之所觉悟，精进行道，慈悲修慧，乘法身船，至涅槃岸。复还生死，度脱众生。以前八事，开导一切，令诸众生，觉生死苦，舍离五欲，修心圣道。若佛弟子，诵此八事，于念念中，灭无量罪，进趣菩提，速登正觉，永断生死，常住快乐。</p><p class="su-tra">这八件事，是一切佛、一切菩萨大人所觉悟过的：他们精进行道，以慈悲修智慧，乘法身的大船，到达涅槃的彼岸；然后又回入生死之中，度脱众生，就用前面这八件事开导一切，让众生觉知生死的苦，舍离五欲，修习圣道。佛的弟子若能诵此八事，在念念之中便灭无量罪，直趋菩提，速登正觉，永断生死，常住快乐。</p></div></div></div>',4)])])}const _=a(i,[["render",t]]);export{v as __pageData,_ as default};
